import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen0Test {





    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal point", NumberUtils.isNumber("123.45"));
        assertTrue("Decimal point with suffix f", NumberUtils.isNumber("123.45f"));
        assertTrue("Decimal point with suffix F", NumberUtils.isNumber("123.45F"));
        assertTrue("Decimal starting with dot", NumberUtils.isNumber(".5"));
        assertTrue("Negative decimal", NumberUtils.isNumber("-123.45"));
        assertFalse("Two decimal points", NumberUtils.isNumber("12.3.4"));
        assertFalse("Decimal with suffix l", NumberUtils.isNumber("12.3l")); // l not allowed with decimal/exp in this logic via suffix check
    }










}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen0Test {







    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue("Scientific notation e", NumberUtils.isNumber("1e10"));
        assertTrue("Scientific notation E", NumberUtils.isNumber("1E10"));
        assertTrue("Scientific notation with sign", NumberUtils.isNumber("1e-10"));
        assertTrue("Scientific notation with plus", NumberUtils.isNumber("1e+10"));
        assertTrue("Scientific notation decimal", NumberUtils.isNumber("1.2e3"));
        assertFalse("E without digit before", NumberUtils.isNumber("e10"));
        assertFalse("E at the end", NumberUtils.isNumber("123E"));
        assertFalse("Two Es", NumberUtils.isNumber("1e2e3"));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("1e1.5"));
        assertFalse("E followed by sign but no digit", NumberUtils.isNumber("1e-"));
    }








}

package org.apache.commons.lang3.math;

