import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.isNumber to maximize branch and line coverage.
 */
public class NumberUtils_isNumber_TriageGen0Test {









    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Hexadecimal lowercase", NumberUtils.isNumber("0x123"));
        assertTrue("Hexadecimal uppercase", NumberUtils.isNumber("0xABC"));
        assertTrue("Hexadecimal with sign", NumberUtils.isNumber("-0x123"));
        assertTrue("Hexadecimal mixed", NumberUtils.isNumber("0x1aF"));
        assertFalse("Hexadecimal incomplete", NumberUtils.isNumber("0x"));
        assertFalse("Hexadecimal invalid chars", NumberUtils.isNumber("0xG12"));
        assertFalse("Hexadecimal with decimal", NumberUtils.isNumber("0x1.2")); // Logic treats hex separately
    }






}

